LICENSE_EN='Free for any use, including commercial use. Attribution is not required; mentioning Verbo is appreciated.'
def card(x):
 return '<article class="tile"><a href="'+x['url']+'"><img src="'+x['thumb']+'" width="480" height="270" loading="lazy" alt="'+e(x['titulo'],quote=True)+'" data-es="'+e(x['titulo'],quote=True)+'" data-en="'+e(x['title_en'],quote=True)+'">'+bi(x['titulo'],x['title_en'],'h2')+'</a><small>'+e(x['cita'])+'</small></article>'
def build():
 ap=argparse.ArgumentParser();ap.add_argument('--todas',action='store_true');ap.add_argument('--banco',type=Path,default=Path.home()/'Verbo/Banco-Imagenes');args=ap.parse_args()
 state=json.loads((args.banco/'estado.json').read_text());records=[]
 for f in sorted((args.banco/'catalogo').glob('*.json')):records.extend(json.loads(f.read_text()))
 out=R/'imagenes';out.mkdir(exist_ok=True)
 old=json.loads((out/'generated.json').read_text()) if (out/'generated.json').exists() else []
 # Remove only prior generated artifacts; never touch hand-authored files.
 for rel in old:
  p=R/rel
  if p.is_relative_to(out) and p.is_file():p.unlink()
 before={p for p in out.rglob('*') if p.is_file()};items=[];ids=set()
 for x in records:
  ident=x['id'];status=state.get(ident,{}).get('estado');book=slug(x['libro'])
  if ident in ids:raise ValueError('Duplicate ID '+ident)
  ids.add(ident)
  if status not in (['aprobada','generada'] if args.todas else ['aprobada']):continue
  if not re.fullmatch('[a-z0-9-]+',ident):raise ValueError('Unsafe ID')
  source=args.banco/'web'/book/(ident+'.jpg')
  if not source.is_file():print('Sin JPG, omitida:',ident);continue
  base=f'/imagenes/{book}/{ident}';dest=R/base.lstrip('/');dest.parent.mkdir(parents=True,exist_ok=True)
  shutil.copyfile(source,str(dest)+'.jpg')
  with Image.open(source) as im:
   im=ImageOps.exif_transpose(im).convert('RGB');ImageOps.fit(im,(480,270)).save(str(dest)+'-mini.jpg',quality=76,optimize=True)
   h=min(im.height,1600);w=round(h*9/16);ImageOps.fit(im,(w,h),centering=(.5,.5)).save(str(dest)+'-vertical.jpg',quality=86,optimize=True)
  y={k:x[k] for k in ('id','libro','testamento','capitulo','versiculos','paralelos','titulo','title_en','tipo','tags','descripcion')};y.update(url=base+'/',original=base+'.jpg',thumb=base+'-mini.jpg',vertical=base+'-vertical.jpg',estado=status,tags_en=[TAGS.get(t,t) for t in x['tags']]);y['cita']=f"{x['libro']} {x['capitulo']}:{x['versiculos']}";y['description_en']=x.get('description_en',f"{x['title_en']}. Bible illustration inspired by {BOOKS.get(x['libro'],x['libro'])} {x['capitulo']}:{x['versiculos']}. Themes: {', '.join(y['tags_en'])}.");items.append(y)
 def write(route,title,desc,body,schema=None):
  page(route,title,desc,body,schema)
  p=R/route/'index.html';s=p.read_text();s=s.replace('</head>','<meta name="keywords" content="imágenes bíblicas gratis, fondos cristianos, wallpaper cristiano, fondos de pantalla cristianos para celular, fondos para proyector de iglesia, ilustraciones bíblicas, free Bible images, Christian wallpaper, Christian backgrounds, church projector backgrounds, Bible illustrations, Bible stock photos">'+('<meta name="robots" content="noindex,nofollow">' if args.todas else '')+'</head>');p.write_text(s)
 license=bi(LICENSE_ES,LICENSE_EN,'p',id='licencia')
 for x in items:
  approved=x['estado']=='aprobada';notice=bi('Imagen generada con IA y revisada por Verbo' if approved else 'Vista previa local: imagen generada con IA, pendiente de revisión por Verbo.','AI-generated image reviewed by Verbo' if approved else 'Local preview: AI-generated image awaiting review by Verbo.','p',**{'class':'notice'})
  body='<a href="/imagenes/">← '+tr('bank','Banco de imágenes','Image library','span')+'</a>'+bi(x['titulo'],x['title_en'],'h1')+bi(x['cita'],x['cita'].replace(x['libro'],BOOKS.get(x['libro'],x['libro'])))
  body+=bi('Paralelos: '+(' · '.join(x['paralelos']) or '—'),'Parallel passages: '+(' · '.join(x['paralelos']) or '—'))+bi(x['descripcion'],x['description_en'])+notice
  body+='<div class="viewer" tabindex="0" role="region" aria-label="Visor: rueda, pellizco o botones para zoom; arrastra para mover"><img draggable="false" src="'+x['original']+'" alt="'+e(x['titulo'],quote=True)+'" data-es="'+e(x['titulo'],quote=True)+'" data-en="'+e(x['title_en'],quote=True)+'"></div><p><button type="button" data-zoom="1.25" aria-label="Acercar / Zoom in">+</button> <button type="button" data-zoom="0.8" aria-label="Alejar / Zoom out">−</button> <button type="button" data-reset>'+tr('reset','Restablecer','Reset','span')+'</button></p>'
  body+=license+'<p><a class="button" download href="'+x['original']+'">'+tr('horizontal','Descargar original 16:9','Download original 16:9','span')+'</a> <a class="button" download href="'+x['vertical']+'">'+tr('vertical','Descargar vertical 9:16','Download vertical 9:16','span')+'</a></p>'+tr('crop','La versión vertical es un recorte central: puede omitir elementos de la escena.','The vertical version is a center crop and may omit elements of the scene.')
  body+='<div class="tags">'+''.join('<a href="/imagenes/temas/'+slug(t)+'/">'+bi(t,TAGS.get(t,t),'span')+'</a>' for t in x['tags'])+'</div><section><h2>'+tr('related','Imágenes relacionadas','Related images','span')+'</h2><div class="grid">'
  related=sorted((z for z in items if z['id']!=x['id']),key=lambda z:len(set(z['tags'])&set(x['tags'])),reverse=True)[:3]
  body+=''.join(card(z) for z in related)+'</div></section><!-- verbo:anuncio:imagen-lectura --><script src="/imagenes/visor.js" defer></script>'
  schema={'@context':'https://schema.org','@type':'ImageObject','name':x['titulo'],'alternateName':x['title_en'],'description':x['descripcion'],'caption':x['cita'],'contentUrl':'https://verbobiblia.com'+x['original'],'thumbnailUrl':'https://verbobiblia.com'+x['thumb'],'license':'https://verbobiblia.com/imagenes/#licencia','creditText':'Verbo','creator':{'@type':'Organization','name':'Verbo'},'inLanguage':['es','en']}
  write(x['url'].strip('/'),x['titulo']+' · '+x['title_en'],x['descripcion'],body,schema)
 tags=Counter(t for x in items for t in x['tags']);collections=[]
 def collection(route,es,en,rows,desc_es,desc_en):
  collections.append((route,es,en));write(route,es+' · '+en,desc_es,'<a href="/imagenes/">← Imágenes / Images</a>'+bi(es,en,'h1')+bi(desc_es,desc_en)+license+'<div class="grid">'+''.join(card(x) for x in rows)+'</div>')
 for book in sorted({x['libro'] for x in items}):collection('imagenes/'+slug(book),'Imágenes de '+book,BOOKS.get(book,book)+' Bible images',[x for x in items if x['libro']==book],'Recorre los pasajes de '+book+' con ilustraciones para acompañar la lectura, preparar clases y compartir el mensaje bíblico.','Explore '+BOOKS.get(book,book)+' with illustrations for reading, teaching and sharing the biblical message.')
 for typ,(es,en) in TYPES.items():collection('imagenes/tipos/'+typ,es,en,[x for x in items if typ=='wallpapers' or slug(x['tipo'])==typ],('Descarga recortes verticales para el fondo de tu celular. Revisa que el encuadre conserve lo que quieres mostrar.' if typ=='wallpapers' else 'Encuentra '+es.lower()+' para enseñar y crear materiales. Revisa cada pasaje y elige una composición adecuada para tu proyecto.'),('Download vertical crops for your phone background. Check that the crop keeps what you want to show.' if typ=='wallpapers' else 'Find '+en.lower()+' for teaching and creative projects. Read the passage and choose a composition that fits your project.'))
 for tag,count in tags.items():collection('imagenes/temas/'+slug(tag),'Imágenes: '+tag,'Bible images: '+TAGS.get(tag,tag),[x for x in items if tag in x['tags']],'Una selección sobre '+tag+' para acompañar tus materiales. Consulta la cita de cada imagen para comprender su contexto bíblico.','A selection about '+TAGS.get(tag,tag)+' for your materials. Read each image’s reference to understand its biblical context.')
 options=''.join('<option value="'+e(b)+'">'+e(b)+'</option>' for b in sorted({x['libro'] for x in items}))
 body=tr('imagesTitle','Imágenes bíblicas gratis','Free Bible images','h1')+tr('imagesLead','Ilustraciones bíblicas, fondos cristianos y paisajes para clases, redes sociales, materiales de iglesia y fondos para proyector. Busca un evento, una cita o una palabra clave; abre la imagen y elige la descarga horizontal o el wallpaper para celular.','Bible illustrations, Christian backgrounds and landscapes for classes, social media, church materials and projector backgrounds. Search by event, reference or keyword, open an image and choose a landscape download or phone wallpaper.')+license
 if args.todas:body+=tr('preview','VISTA PREVIA LOCAL: incluye imágenes pendientes de revisión. No publicar esta compilación.','LOCAL PREVIEW: includes images awaiting review. Do not publish this build.','p')
 body+='<form class="filters" role="search"><label>Buscar / Search <input id="query" type="search" placeholder="Mt 14 · Mateo 14:13 · Mr 6:30-44 · prayer"></label><label>Libro / Book <select id="book"><option value="">Todos / All</option>'+options+'</select></label><label>Testamento / Testament <select id="testament"><option value="">Todos / All</option><option>NT</option><option>AT</option></select></label><label>Tipo / Type <select id="type"><option value="">Todos / All</option>'+''.join('<option value="'+k+'">'+a+' / '+b+'</option>' for k,(a,b) in TYPES.items() if k!='wallpapers')+'</select></label></form><p id="results" role="status" aria-live="polite"></p><div class="grid" id="image-grid">'+''.join(card(x)+('<!-- verbo:anuncio:banco-entre-filas -->' if i==7 else '') for i,x in enumerate(items[:12]))+'</div><noscript><p>Explora las colecciones para ver todas las imágenes. / Browse collections to see every image.</p></noscript><h2>'+tr('collections','Explora las colecciones','Browse collections','span')+'</h2><div class="tags">'+''.join('<a href="/'+r+'/">'+bi(a,b,'span')+'</a>' for r,a,b in collections if '/temas/' not in r or tags[a.replace('Imágenes: ','')]>=4)+'</div><script src="/imagenes/buscador.js" defer></script>'
 write('imagenes','Imágenes bíblicas gratis · Free Bible images', 'Imágenes bíblicas gratis, fondos cristianos y wallpapers para celular. Free Bible images, Christian wallpaper and church projector backgrounds.',body)
 (out/'indice.json').write_text(json.dumps(items,ensure_ascii=False,separators=(',',':'))+'\n')
 save();generated=sorted(str(p.relative_to(R)) for p in out.rglob('*') if p.is_file() and p not in before);(out/'generated.json').write_text(json.dumps(generated,indent=2)+'\n');print(f'Banco: {len(items)} imágenes; {len(collections)} colecciones; vista previa={args.todas}')
if __name__=='__main__':
 build()
 from pie_comun import apply
 apply()
